import{_ as e,H as a,f as l,i as t}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"开篇词 | 带你吃透DDD","description":"","frontmatter":{},"headers":[{"level":2,"title":"落地 DDD 有哪些困难？","slug":"落地-ddd-有哪些困难","link":"#落地-ddd-有哪些困难","children":[]},{"level":2,"title":"DDD 怎样才能“更好学”？","slug":"ddd-怎样才能-更好学","link":"#ddd-怎样才能-更好学","children":[{"level":3,"title":"第一，基于认知规律","slug":"第一-基于认知规律","link":"#第一-基于认知规律","children":[]},{"level":3,"title":"迭代一：夯实基础","slug":"迭代一-夯实基础","link":"#迭代一-夯实基础","children":[]},{"level":3,"title":"迭代二：渐入佳境","slug":"迭代二-渐入佳境","link":"#迭代二-渐入佳境","children":[]},{"level":3,"title":"迭代三：掌握更高级的技能","slug":"迭代三-掌握更高级的技能","link":"#迭代三-掌握更高级的技能","children":[]},{"level":3,"title":"第二，是立足原书，有所发展","slug":"第二-是立足原书-有所发展","link":"#第二-是立足原书-有所发展","children":[]},{"level":3,"title":"第三，是补足面向对象基础","slug":"第三-是补足面向对象基础","link":"#第三-是补足面向对象基础","children":[]},{"level":3,"title":"最后，是面向实践，避免空谈","slug":"最后-是面向实践-避免空谈","link":"#最后-是面向实践-避免空谈","children":[]}]},{"level":2,"title":"写在最后","slug":"写在最后","link":"#写在最后","children":[]}],"relativePath":"手把手教你落地DDD/开篇词｜带你吃透DDD.md","filePath":"手把手教你落地DDD/开篇词｜带你吃透DDD.md","lastUpdated":1795557830000}'),i={name:"手把手教你落地DDD/开篇词｜带你吃透DDD.md"};function p(r,D,d,n,h,o){return a(),l("div",null,[...D[0]||(D[0]=[t('<h1 id="开篇词-带你吃透ddd" tabindex="-1">开篇词 | 带你吃透DDD <a class="header-anchor" href="#开篇词-带你吃透ddd" aria-label="Permalink to &quot;开篇词 | 带你吃透DDD&quot;">​</a></h1><p>你好，我是钟敬，欢迎和我一起来学习领域驱动设计。</p><p>我是一名在 IT 界奋斗了二十多年的老兵。目前在 Thoughtworks 公司担任首席咨询师，也是数字化转型与运营团队的 DDD 交付负责人。平时的工作主要是给客户提供软件开发方法学、架构治理、研发效能提升等方面的帮助。</p><p>DDD，也就是“领域驱动设计”，在软件工程里，属于软件开发方法学的范畴。它继承了面向对象和敏捷方法的精华，并提炼了一套更容易掌握的原则、模式和实践，特别适合复杂的企业应用的开发。</p><p>这些年，随着数字化转型的浪潮，我们为很多家大中型企业，在几十个项目里引入了 DDD，解决了很多实际的痛点和问题。</p><p>比如说，有的企业的业务很复杂，业务人员和开发人员总是很难把需求完全说清楚，直到写完代码，用户测试的时候，才知道开发人员的理解跑偏了。采用了 DDD 以后，就可以利用领域建模，把业务知识充分地严格化和可视化。这样，在分析设计阶段，就能对齐业务和开发的理解。</p><p>还有一些系统的需求变化很快，开发很难跟上业务的节奏。有时为了能够在短期内应付变化，又会写出“打补丁”式的代码，给系统留下隐患。这种情况下，采用领域建模的方法，把领域知识抽象化，把相对稳定和相对变化的部分分开，并把变化的部分设计成可插拔、可配置的，就能开发出灵活、易扩展的系统。</p><p>另外，还有一些项目希望采用微服务架构，但是缺乏拆分的依据，不知道怎么确定服务的粒度和边界。这时通过 DDD 的领域建模和限界上下文的划分，就可以给微服务的拆分提供坚实的基础。</p><p>还有一种常见的问题，就是有些企业系统的架构和代码已经严重腐化了，希望通过重构来提高质量和可维护性。但是，应该往哪个方向重构呢？怎么在重构过程中降低风险，并且兼顾业务需求呢？</p><p>借助 DDD，就可以通过一套系统化的方法，为系统建立目标模型和设计目标架构。同时，再利用 DDD 的“柔性设计”，并且结合演进式架构和代码重构等等技术，就能很好地解决问题。</p><h2 id="落地-ddd-有哪些困难" tabindex="-1">落地 DDD 有哪些困难？ <a class="header-anchor" href="#落地-ddd-有哪些困难" aria-label="Permalink to &quot;落地 DDD 有哪些困难？&quot;">​</a></h2><p>事实上，我们发现，在开发微服务，遗留系统改造、架构治理、企业架构、研发效能提升、架构师培养等很多方面，DDD 都有用武之地。</p><p>DDD 有这么多的优势，可是在实践的时候，不少小伙伴都觉得不太容易学习和落地。在我们推广的过程里，发现主要有下面这几个难点。</p><p>第一，是领域建模不好掌握。不论是在 DDD，还是传统的面向对象方法学里面，领域建模都是整个过程的核心，这里面还是有不少的方法和技巧的。不过《领域驱动设计：软件核心复杂性应对之道》（以下简称《DDD》）原书的作者，大概是假设读者已经有一定的面向对象建模基础了，所以有些东西讲得也不太透。</p><p>第二，领域模型不好实现。也就是说，就算有人把领域模型建好了，不少团队也不会按照领域模型去设计数据库，设计架构，并且编写代码。而 DDD 强调，领域模型的实现必须和模型本身保持高度一致。那么，同样是因为面向对象的基础不牢，所以不懂模型的实现方法。这方面，在原书里，也没有说得太明白。</p><p>第三，是概念混乱。有些小伙伴可能已经看了不少书，听了不少讲座，但是发现 DDD 的很多概念，老师们说的好像都不一样，不知道到底该信谁的。这是因为很多人没有看原著，或者没看懂。结果，反而接受了很多二手、三手的材料。有些材料又是理解不一，甚至以讹传讹。</p><p>第四，是时代的发展。现在离 DDD 的提出，已经有二十年了。不论是技术环境还是开发理念，都已经发生了不小的变化。如果不能与时俱进，对 DDD 原来的一些理念和方法进行发展，那也很难落地。</p><p>最后，还有很多具体落地时才会遇到的问题。就算某个人自己已经掌握得很不错了，但是在团队里一推广，又会有很多障碍。比如说怎么让新、旧开发方法共存；怎么把 DDD 融入到日常开发流程；怎么评估 DDD 实施的成效等等。</p><h2 id="ddd-怎样才能-更好学" tabindex="-1">DDD 怎样才能“更好学”？ <a class="header-anchor" href="#ddd-怎样才能-更好学" aria-label="Permalink to &quot;DDD 怎样才能“更好学”？&quot;">​</a></h2><p>虽然说了不少困难，但是你也大可不必担心。DDD 的学习还是有方法，有套路的。我希望通过这门课，把 DDD 的原理和我们在实践里总结的经验，分享给你。</p><p>为了帮你和你的团队顺利掌握和落地 DDD，解决前面说的疑难问题，这门课在设计时遵循了四个原则，我们一个一个说一下。</p><h3 id="第一-基于认知规律" tabindex="-1">第一，基于认知规律 <a class="header-anchor" href="#第一-基于认知规律" aria-label="Permalink to &quot;第一，基于认知规律&quot;">​</a></h3><p>这门课基于一个贯穿始终的案例（企业管理系统）。这个案例模拟了敏捷软件开发过程，分成了三个迭代。每个迭代分成若干节课，每节课一方面引入新的知识，另一方面也会呼应和深化之前的知识。这三个迭代是这么安排的。</p><h3 id="迭代一-夯实基础" tabindex="-1">迭代一：夯实基础 <a class="header-anchor" href="#迭代一-夯实基础" aria-label="Permalink to &quot;迭代一：夯实基础&quot;">​</a></h3><p>第一个迭代，我们会开启一个“麻雀虽小，五脏俱全”的项目（配套代码链接从这里获取）。通过这个迭代，你就可以打通一个“需求 - 模型 - 代码”的最小闭环，对 DDD 的过程初步形成一个完整的“感觉”。</p><p>首先，我会利用 DDD 世界里一种常用的方法“事件风暴”，来和你一起梳理行为需求。在这个过程中，也会介绍“统一语言”。之后，我们一起来实操 DDD 的核心技能“领域建模”，并引入实体、关联、模块等几个重要的模式。接下来是模型的实现，也就是根据模型建立数据库和编写代码。你会学到 DDD 的分层架构，工厂、仓库、领域服务等模式。还会涉及到到怎样封装、怎样实现领域逻辑等等。</p><p>学完这个迭代，你应该能打下一个比较好的基础，并且有能力试着处理一些不太复杂的项目了。</p><h3 id="迭代二-渐入佳境" tabindex="-1">迭代二：渐入佳境 <a class="header-anchor" href="#迭代二-渐入佳境" aria-label="Permalink to &quot;迭代二：渐入佳境&quot;">​</a></h3><p>第二个迭代，我们进一步深入，讲几个 DDD 里争议较大，不太好掌握的内容。</p><p>我会先从理论、模型和编码层面帮你理解“聚合”。同时，会进一步带你提升领域建模能力，深化对分层架构和代码封装的理解。接着，我们会用几节课讲值对象，带你理解值对象的本质和优点，并解决值对象在建模和编程上的一些具体问题。最后，我们会学习一个重要的建模技巧——泛化，这是领域建模由初级走向中、高级的关键技能。</p><p>经过第二个迭代的揣摩，你应该会有渐入佳境的感觉了。</p><h3 id="迭代三-掌握更高级的技能" tabindex="-1">迭代三：掌握更高级的技能 <a class="header-anchor" href="#迭代三-掌握更高级的技能" aria-label="Permalink to &quot;迭代三：掌握更高级的技能&quot;">​</a></h3><p>经过前两个迭代，你对一个开发组范围内的项目应该有一定信心了。但是如果项目范围更大，该怎么处理呢？</p><p>在第三个迭代，我会介绍“限界上下文”模式，通过分而治之来维护概念的一致性。在这个基础上，再进一步学习微服务设计。</p><p>接下来，我会带你了解事件驱动和 CQRS 这两个重要的架构模式。然后，我们会讨论怎样为更加灵活多变的业务建模，并深化对泛化的理解。最后，我们会解决在实际落地过程中会遇到的几个问题，比如 DDD 切入点的选择，遗留系统的改造等等。</p><p>经过这三个迭代的学习，你已经掌握了 DDD 最核心的技能，再经过一段时间的实践和消化，就可以向 DDD“专家”迈进了。</p><h3 id="第二-是立足原书-有所发展" tabindex="-1">第二，是立足原书，有所发展 <a class="header-anchor" href="#第二-是立足原书-有所发展" aria-label="Permalink to &quot;第二，是立足原书，有所发展&quot;">​</a></h3><p>这门课基于《DDD》原书的理论框架，力求准确地反映书里的知识体系。但这也并不意味着本本主义，不是说书里的一定就是对的。我会首先解释清楚原书的概念，并对值得商榷的地方做深入分析。对原书里没有讲透的部分，也会通过实例进一步讲解。</p><p>随着时代的发展，还出现了和 DDD 相关的新内容和新观点，比如前面提到过的微服务设计、事件驱动架构、CQRS，还有对贫血模型和富领域模型的权衡等等，这些你都会在课程里讲到。</p><h3 id="第三-是补足面向对象基础" tabindex="-1">第三，是补足面向对象基础 <a class="header-anchor" href="#第三-是补足面向对象基础" aria-label="Permalink to &quot;第三，是补足面向对象基础&quot;">​</a></h3><p>前面说过，《DDD》原书的作者，其实是假设读者已经有了一定面向对象方法学的基础，比如说，分析和设计的基本理念、UML 的使用、模型到代码的转换等等。不过学习这门课，不需要你系统地掌握面向对象方法学。我会在讲解过程中，结合 DDD 的知识点，详细介绍必要的面向对象知识和技能，帮助你扫清学习障碍。</p><h3 id="最后-是面向实践-避免空谈" tabindex="-1">最后，是面向实践，避免空谈 <a class="header-anchor" href="#最后-是面向实践-避免空谈" aria-label="Permalink to &quot;最后，是面向实践，避免空谈&quot;">​</a></h3><p>这门课基本上都是按照“问题 - 方案”的模式。也就是说，首先由需求引发要解决的问题，然后找到解决问题的知识点，并进行讲解。每个知识点都有具体的建模或编码实现来说明，避免空谈理论。</p><h2 id="写在最后" tabindex="-1">写在最后 <a class="header-anchor" href="#写在最后" aria-label="Permalink to &quot;写在最后&quot;">​</a></h2><p>和很多 IT 技术一样，DDD 不是纯理论的，而是一门“手艺”，必须动手练习才能真正学懂。</p><p>你可以跟着我建模型、写代码，拾级而上。最终，让你在心里潜移默化地建立起完整的知识图景，掌握 DDD 最核心的技能。如果可以在自己的项目里用起来，感受应该会更加深刻。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/1.png" alt=""></a></p><ul><li>知识地图</li></ul><p>当你学到课程中间部分的时候，就可以读一下《DDD》原书来加深理解，还可以通过其他参考书扩展视野。比如说，如果想深入学习 UML，可以读一下《UML 用户指南》和《UML 精粹》；想了解真正复杂的领域模型长什么样，可以看看《分析模式：可复用的对象模型》等等。另外，你还可以把自己学习到的知识，讲给团队的小伙伴听，达到教学相长的目的。</p><p>最后，我想说的是，DDD 不仅是一门技术，更是一门艺术。而你既然想学习 DDD，恐怕也不仅仅是为了应付某个具体的问题，而是多少带着一些情怀来的。你可能想要了解，几十年来，那些研究软件开发方法学的大师们，到底总结出了怎样的经验；也可能希望发扬工匠精神，成为一个技艺卓越的软件开发者。</p><p>那么，就让我们一起，开始这个充满乐趣的探索之旅吧。戳此加入，专栏交流群。</p>',51)])])}const u=e(i,[["render",p]]);export{c as __pageData,u as default};
